!function(t){function r(r){for(var n,a,o=r[0],m=r[1],u=r[2],c=0,g=[];c<o.length;c++)a=o[c],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&g.push(i[a][0]),i[a]=0;for(n in m)Object.prototype.hasOwnProperty.call(m,n)&&(t[n]=m[n]);for(f&&f(r);g.length;)g.shift()();return p.push.apply(p,u||[]),e()}function e(){for(var t,r=0;r<p.length;r++){for(var e,a=p[r],o=!0,m=1;m<a.length;m++)e=a[m],0!==i[e]&&(o=!1);o&&(p.splice(r--,1),t=n(n.s=a[0]))}return t}function n(r){if(a[r])return a[r].exports;var e=a[r]={i:r,l:!1,exports:{}};return t[r].call(e.exports,e,e.exports,n),e.l=!0,e.exports}var a={},i={16:0},p=[];n.m=t,n.c=a,n.d=function(t,r,e){n.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:e})},n.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},n.t=function(t,r){if(1&r&&(t=n(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var e=Object.create(null);if(n.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var a in t)n.d(e,a,function(r){return t[r]}.bind(null,a));return e},n.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return n.d(r,"a",r),r},n.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},n.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=r,o=o.slice();for(var u=0;u<o.length;u++)r(o[u]);var f=m;p.push([31,0]),e()}({31:function(t,r,e){"use strict";e.r(r);var n=e(0);Object(n.a)("uk","army",e(32),e(1))},32:function(t){t.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"“谢尔曼·莹火虫”坦克","description":"<h6>综述：</h6><p>二战期间，英国对美国研发生产的M4系列中型坦克改造最成功的是安装了17磅（76.2mm）高速火炮的“莹火虫”系列坦克。该型火炮的安装弥补了美军M4火力不足的缺陷，加上原M4坦克的厚装甲，使得“谢尔曼·莹火虫”坦克具有了能够与德军坦克抗衡的能力。“谢尔曼·莹火虫”坦克以装上英式17磅火炮的原型车的型号作区分，有“谢尔曼·莹火虫”MK.ⅠC（M4中型坦克改良型）和“谢尔曼·莹火虫”MK.ⅤC（M4A4中型坦克改良型）。“谢尔曼·莹火虫”自生产后一直供不应求，具体生产数量各资料目前也未有一个准确的数字，生产数量应在2000辆上下，该款坦克除大量装备英军外，也有不少装备了波兰第1装甲师等盟国其它军队。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}1945年夏季，洛雷托地区，波兰第2装甲旅第6装甲团第1中队的一辆编号为“T26537”的“谢尔曼·莹火虫”MK.ⅠC坦克。{{image}}imgs/uk/army/uk_army_tankff_11.jpg{{text}}1945年8月荷兰战场，波兰第1装甲师第24团的一辆“谢尔曼·莹火虫”MK.ⅠC坦克。{{image}}imgs/uk/army/uk_army_tankff_12.jpg{{text}}1945春意大利战场，波兰第1枪骑兵团第3中队编号为“T269854”的一辆“谢尔曼·莹火虫”MK.ⅠC坦克。{{image}}imgs/uk/army/uk_army_tankff_13.jpg","description":"<h6>“谢尔曼·莹火虫”MK.ⅠC坦克</h6><p>该型坦克是以美国M4中型坦克为主体，换装英式17磅火炮而成。17磅炮采用采用新式防盾，炮塔侧面的机枪射击口被封闭焊死，车载无线电装置也被移至炮塔后部的装甲盒子内。“莹火虫”坦克使用的是钝头被帽穿甲弹，在入射角为30度，它可以在500m距离击穿140装甲，1944年8月后，配备了高速脱壳穿甲弹，此弹可在500m距离击穿200mm厚装甲，由此可见，该型坦克的17磅火炮已可以在500m距离击穿德军重型坦克的装甲，尽管高速脱壳穿甲弹威力大，理论上也可以在远距离 （1000m外）击穿德军虎式坦克装甲，但由于其射击精度不高，远距离根本无法准确射中目标，因此英军要求只有近距才使用此弹。</p><p>除火炮作了改装外，“谢尔曼·莹火虫”MK.ⅠC坦克与M4中型坦克参数基本是相同的（车重会比M4稍重一些）。</p>","caption":""},{"image":"{{text}}“谢尔曼·莹火虫”MK.ⅤC坦克三视图{{image}}imgs/uk/army/uk_army_tankff_21.jpg{{text}}1944年6月诺曼底战场，英军第7装甲师伦敦第4郡约曼利团的一辆“谢尔曼·莹火虫”MK.ⅤC坦克。{{image}}imgs/uk/army/uk_army_tankff_22.jpg{{text}}1944年8月诺曼底战场，波兰第1装甲师第2装甲团的一辆“谢尔曼·莹火虫”MK.ⅤC坦克。{{image}}imgs/uk/army/uk_army_tankff_23.jpg","description":"<h6>“谢尔曼·莹火虫”MK.ⅤC坦克</h6><p>该型坦克是以美国M4A4中型坦克为主体，换装英式17磅火炮而成，它是“莹火虫”坦克的主要量产型号，它的公路最大车速是40km/h，战斗全重为32.2t。</p><p>坦克其它参数与美制M4A4中型坦克基本相同。</p><p>实战发现，尽管“谢尔曼·莹火虫”坦克的火炮有优秀的反坦克能力，但对付如步兵、建筑群和轻型装甲车等“软”目标时，战效要比原型车差。</p>","caption":""}],"part2title":"战场上的“谢尔曼·莹火虫”坦克","part2description":"<p>“谢尔曼·莹火虫”坦克在1943年开始装备英军后，由于在战场上的出色表现，就一直成为英军装甲部队的主力坦克。由于生产跟不上，到1944年6月诺曼底登陆战时，英军仍只能每个坦克排（分队）分配一辆“谢尔曼·莹火虫”坦克，其它为装备75mm火炮的M4系列原型车，直到1944年8月后，欧洲战场上各装甲单位装备的“谢尔曼·莹火虫”坦克才逐渐增加，达到了与其它坦克（“克伦威尔”和“谢尔曼”）1：1的配备。</p><p>在诺曼底登陆战中，德军第21装甲师突入海滩被英军伏击，德军损失了13辆坦克，其中有7辆是被英军斯塔福德郡义勇骑兵团的“莹火虫”坦克所击毁。在卡昂战场，也是靠“莹火虫”坦克挡住德军的去路。在1944年6月在守卫兰热夫雷村的战斗中，英军一龙骑兵团的“莹火虫”坦克击毁了德军第130装甲教导师的5辆豹坦克。在7月中旬，英军的一辆“莹火虫”坦克首次击毁了一辆隶属德军503重装营的虎式坦克。而德国著名坦克手魏特曼的坦克被击毁致魏特曼本人死亡，也有资料说是受英军“莹火虫”坦克伏击而造成的。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankff_31.jpg","description":"1944年6月，在法国诺曼底战场，英军斯塔福德郡义勇骑兵团的一辆“莹火虫”坦克正隐蔽在灌木林中，准备伏击德军坦克部队。","caption":""},{"image":"imgs/uk/army/uk_army_tankff_32.jpg","description":"1944年7月，在法国奥恩河畔集结的英国第1皇家坦克团的“莹火虫”坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankff_33.jpg","description":"1944年7月，在法国奥恩河畔集结的英军第11装甲师第3坦克团的“莹火虫”MK.ⅤC坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankff_34.jpg","description":"1944年法国战场，英军一辆“莹火虫”坦克的乘员正在给坦克装弹，作下次战斗的准备。","caption":""},{"image":"imgs/uk/army/uk_army_tankff_35.jpg","description":"1944年6月，波兰第1装甲师第2装甲团的2辆“莹火虫”MK.ⅤC坦克与2辆谢尔曼（M4A4)坦克在英国基地作配合作战训练。","caption":""},{"image":"imgs/uk/army/uk_army_tankff_36.jpg","description":"1944年11月，波兰第1装甲师第1装甲团的“莹火虫”MK.ⅤC坦克攻入荷兰一城镇。","caption":""},{"image":"imgs/uk/army/uk_army_tankff_37.jpg","description":"1944年10月，波兰第1装甲师一辆“莹火虫”MK.ⅤC坦克进入一个刚收复的比利时城镇。","caption":""}]}')}});